import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Arrow-Native Modules","description":"","frontmatter":{"title":"Arrow-Native Modules","type":"adr","date":"2026-09-01T00:00:00.000Z","status":"accepted","status_note":"Accepted — a file is an arrow; imports are projection."},"headers":[],"relativePath":"handl/project/adrs/0069-arrow-native-modules.md","filePath":"vendored/handl/project/adrs/0069-arrow-native-modules.md"}`),a={name:`handl/project/adrs/0069-arrow-native-modules.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0069-arrow-native-modules" tabindex="-1">ADR-0069: Arrow-Native Modules <a class="header-anchor" href="#adr-0069-arrow-native-modules" aria-label="Permalink to “ADR-0069: Arrow-Native Modules”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>A file is an arrow.</strong> A module is the arrow its file evaluates to, not a namespace or environment.</li><li><strong>Import normalizes to projection</strong>: importing a name is selecting a field of the module arrow&#39;s result.</li><li><strong>Using a name is <code>App</code></strong> — a reference is application of a projection, not a scope lookup.</li><li><strong>Two caches: graphs and contracts.</strong> Normalized module graphs and their contracts are cached separately.</li><li><strong>Normalization is one abstraction with many implementations</strong>; the strategy is a choice, not a hardcoded path.</li><li><strong>No <code>export</code>, no visibility, no environments.</strong> Those concepts disappear because a module is already a value.</li><li><strong>Multi-file programs are arrow composition</strong> — linking is composition.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Modules were environments with export/visibility rules, and every consumer re-implemented lookup. If a file is an arrow, import is projection and use is application — two operations already in the calculus — so the module system needs no separate semantics.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep export/visibility/environments</strong> — they are the special cases arrows remove.</li><li><strong>Eager evaluation of imports</strong> — normalization is lazy and cached.</li><li><strong>One hardcoded normalizer</strong> — the strategy is an abstraction.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Import/use lower to projection/application; no new kernel primitives.</li><li>Two caches must agree; invalidation is per module graph/contract.</li><li>Multi-file linking is composition; no linker phase.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — module loading and projection.</li><li><code>handl-runtime/</code> — the graph and contract caches.</li><li>Module tests in <code>handl-runtime/tests/</code> and <code>engine-exec-*</code>.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The seven rules in full, behavior examples and the five composition operations: +<a href="./../design/0069-arrow-native-modules.html"><code>design/0069-arrow-native-modules.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};